<?php
$contexts=['home'=>t('Homepage'),'categories'=>t('Category list page'),'article'=>t('All article pages'),'archive'=>t('Archive pages')];
foreach(query("SELECT id,title FROM pages WHERE kind='custom' ORDER BY id")->fetchAll() as $entry)$contexts['page:'.$entry['id']]=$entry['title'];
$layoutContext=(string)($_GET['context']??'home');if(!isset($contexts[$layoutContext]))$layoutContext='home';$layout=layoutItems($layoutContext);
?>
<section class="panel admin-panel"><h2><?=e(t('Page layout'))?></h2><label class="layout-context-label" for="layout-context"><?=e(t('Select page layout'))?></label><select id="layout-context"><?php foreach($contexts as $key=>$label):?><option value="<?=e($key)?>" <?=$key===$layoutContext?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><p class="muted"><?=e(t('Choose a region in the diagram to configure its widgets. Changes apply after saving.'))?></p></section>
<section id="layout-editor" class="backend-layout-editor" data-context="<?=e($layoutContext)?>">
<div class="panel layout-diagram"><div class="diagram-fixed"><?=e(t('Header menu'))?></div><div id="layout-regions"></div><div class="diagram-fixed"><?=e(t('Footer settings'))?></div></div>
<div class="panel layout-configuration"><h2 id="region-heading"></h2><div id="layout-rows"></div><div class="customizer-add"><label for="widget-type"><?=e(t('Widget'))?></label><select id="widget-type"><?php foreach(widgetTypes() as $key=>$label):if(($key==='toc'&&$layoutContext!=='article')||($layoutContext==='article'&&in_array($key,['posts','categories'],true)))continue;?><option value="<?=$key?>"><?=e(t($label))?></option><?php endforeach;?></select><button type="button" class="text-button" id="add-widget"><?=e(t('Add widget'))?></button></div><div class="customizer-actions"><p role="status" id="layout-message"></p><button type="button" class="button" id="save-layout"><?=e(t('Save and apply'))?></button><button type="button" class="text-button" id="reset-layout"><?=e(t('Restore default'))?></button></div></div>
<script type="application/json" id="layout-data"><?=json_encode($layout,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?></script><script type="application/json" id="layout-zones"><?=json_encode(array_map('t',layoutZones()),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?></script></section><script src="/assets/layout.js?v=5" defer></script>
